/** The directories above `rel` (relative, nearest last), excluding the tree root. */
function ancestors(rel: string): string[] {
  const out: string[] = [];
  for (let dir = path.dirname(rel); dir !== "." && dir !== "/"; dir = path.dirname(dir)) out.unshift(dir);
  return out;
