  const collapsed = nul(git(sourceRoot, [...base, "--directory", `--exclude-from=${file}`]).stdout);
  return { roots: collapsed.filter((entry) => { const rel = entry.replace(/\/$/, ""); return files.has(rel) || dirs.has(rel); }), only: { files, dirs } };
